        "choices": ["undefended", "scrubbed"]
    })

    split: str = field(default="train", metadata={
        "help": "the split this dataset is loading. "
    })

    sample_duplication_rate: int = field(default=1, metadata={
        "help": "Number of times to repeat a sample"
